private void doWrite(SelectionKey key, ByteBuffer buf) throws IOException {
    SocketChannel ch = (SocketChannel) key.channel();
    ch.write(buf);
    if (buf.hasRemaining()) {
        pending.put(key, buf);                              // 没写完，存起来
        key.interestOps(key.interestOps() | SelectionKey.OP_WRITE);   // 注册写事件
    } else {
        key.interestOps(key.interestOps() & ~SelectionKey.OP_WRITE);  // 写完取消
    }
}

